79	export function applyReplacement(
80	  currentContent: string | null,
81	  oldString: string,
82	  newString: string,
83	  isNewFile: boolean,
84	): string {
85	  if (isNewFile) {
86	    return newString;
87	  }
88	  if (currentContent === null) {
89	    // Should not happen if not a new file, but defensively return empty or newString if oldString is also empty
90	    return oldString === '' ? newString : '';
91	  }
92	  // If oldString is empty and it's not a new file, do not modify the content.
93	  if (oldString === '' && !isNewFile) {
94	    return currentContent;
95	  }
96	
97	  // Use intelligent replacement that handles $ sequences safely
98	  return safeLiteralReplace(currentContent, oldString, newString);
99	}
