110	function restoreTrailingNewline(
111	  originalContent: string,
112	  modifiedContent: string,
113	): string {
114	  const hadTrailingNewline = originalContent.endsWith('\n');
115	  if (hadTrailingNewline && !modifiedContent.endsWith('\n')) {
116	    return modifiedContent + '\n';
117	  } else if (!hadTrailingNewline && modifiedContent.endsWith('\n')) {
118	    return modifiedContent.replace(/\n$/, '');
119	  }
120	  return modifiedContent;
121	}
