132	async function calculateExactReplacement(
133	  context: ReplacementContext,
134	): Promise<ReplacementResult | null> {
135	  const { currentContent, params } = context;
136	  const { old_string, new_string } = params;
137	
138	  const normalizedCode = currentContent;
139	  const normalizedSearch = old_string.replace(/\r\n/g, '\n');
140	  const normalizedReplace = new_string.replace(/\r\n/g, '\n');
141	
142	  const exactOccurrences = normalizedCode.split(normalizedSearch).length - 1;
143	
144	  if (!params.allow_multiple && exactOccurrences > 1) {
145	    return {
146	      newContent: currentContent,
147	      occurrences: exactOccurrences,
148	      finalOldString: normalizedSearch,
149	      finalNewString: normalizedReplace,
150	    };
151	  }
152	
153	  if (exactOccurrences > 0) {
154	    let modifiedCode = safeLiteralReplace(
155	      normalizedCode,
156	      normalizedSearch,
157	      normalizedReplace,
158	    );
159	    modifiedCode = restoreTrailingNewline(currentContent, modifiedCode);
160	    return {
161	      newContent: modifiedCode,
162	      occurrences: exactOccurrences,
163	      finalOldString: normalizedSearch,
164	      finalNewString: normalizedReplace,
165	    };
166	  }
167	
168	  return null;
169	}
