171	async function calculateFlexibleReplacement(
172	  context: ReplacementContext,
173	): Promise<ReplacementResult | null> {
174	  const { currentContent, params } = context;
175	  const { old_string, new_string } = params;
176	
177	  const normalizedCode = currentContent;
178	  const normalizedSearch = old_string.replace(/\r\n/g, '\n');
179	  const normalizedReplace = new_string.replace(/\r\n/g, '\n');
180	
181	  const sourceLines = normalizedCode.match(/.*(?:\n|$)/g)?.slice(0, -1) ?? [];
182	  const searchLinesStripped = normalizedSearch
183	    .split('\n')
184	    .map((line: string) => line.trim());
185	  const replaceLines = normalizedReplace.split('\n');
186	
187	  let flexibleOccurrences = 0;
188	  let i = 0;
189	  while (i <= sourceLines.length - searchLinesStripped.length) {
190	    const window = sourceLines.slice(i, i + searchLinesStripped.length);
191	    const windowStripped = window.map((line: string) => line.trim());
192	    const isMatch = windowStripped.every(
193	      (line: string, index: number) => line === searchLinesStripped[index],
194	    );
195	
196	    if (isMatch) {
197	      flexibleOccurrences++;
198	      const firstLineInMatch = window[0];
199	      const indentationMatch = firstLineInMatch.match(/^([ \t]*)/);
200	      const indentation = indentationMatch ? indentationMatch[1] : '';
201	      const newBlockWithIndent = applyIndentation(replaceLines, indentation);
202	      sourceLines.splice(
203	        i,
204	        searchLinesStripped.length,
205	        newBlockWithIndent.join('\n'),
206	      );
207	      i += replaceLines.length;
208	    } else {
209	      i++;
210	    }
211	  }
212	
213	  if (flexibleOccurrences > 0) {
214	    let modifiedCode = sourceLines.join('');
215	    modifiedCode = restoreTrailingNewline(currentContent, modifiedCode);
